"""Hand-authored edge fixture outside the synthetic generator's case loop."""

from __future__ import annotations

import csv
import json
import tempfile
from collections import Counter
from datetime import date, timedelta
from pathlib import Path

from gen.synthetic import HEADERS
from reconcile_engine import reconcile
from warehouse import connect, ingest, trace


# Each tuple is (reference, bank cents, bank day offsets, expected label).
# All ledger amounts are -10,000 SGD cents on 2026-09-01. The labels were
# hand-specified from the desired financial rule boundaries, not generated by
# the production fixture generator or read by the matcher.
CASES = (
    ("EDGE-01", (-10_000,), (0,), "matched"),
    ("EDGE-02", (-10_000,), (3,), "timing_difference"),
    ("EDGE-03", (-10_000,), (4,), "unexplained"),
    ("EDGE-04", (-10_100,), (0,), "fee_fx_difference"),
    ("EDGE-05", (-10_101,), (0,), "unexplained"),
    ("EDGE-06", (-10_000, -10_000), (0, 0), "duplicate"),
    ("EDGE-07", (-4_000, -6_000), (0, 0), "many_to_one"),
    ("EDGE-08", (-1_000, -2_000, -3_000, -4_000), (0, 0, 0, 0), "many_to_one"),
    ("EDGE-09", (-1_000, -1_000, -1_000, -1_000, -6_000), (0, 0, 0, 0, 0), "unexplained"),
    ("EDGE-10", (), (), "missing_in_bank"),
    ("EDGE-11", (-4_000, -5_000), (0, 0), "unexplained"),
    ("EDGE-12", (-10_000, -10_000), (0, 5), "unexplained"),
    ("EDGE-13", (-4_000, -6_000), (0, 4), "unexplained"),
    ("EDGE-14", (-9_900,), (0,), "fee_fx_difference"),
)


def _write(path: Path, source: str, rows: list[dict]) -> None:
    with path.open("w", newline="", encoding="utf-8") as file:
        writer = csv.DictWriter(file, fieldnames=HEADERS[source])
        writer.writeheader()
        writer.writerows(rows)


def run(report_dir: Path | None = None) -> dict:
    with tempfile.TemporaryDirectory(prefix="finrecon-edge-") as folder:
        root = Path(folder)
        data = root / "sources"
        data.mkdir()
        ledger, bank = [], []
        expected = {reference: label for reference, _, _, label in CASES}
        base = date(2026, 9, 1)
        for ref, amounts, offsets, _ in CASES:
            ledger.append({"id": f"L-{ref}", "reference": ref,
                           "posted_on": base.isoformat(),
                           "posted_at": f"{base.isoformat()}T10:00:00+08:00",
                           "counterparty": "Edge Vendor",
                           "currency": "SGD", "amount_cents": -10_000,
                           "account": "AP-SETTLEMENT", "contra_account": "CASH",
                           "created_by": "clerk",
                           "approved_by": "manager"})
            for index, (amount, days) in enumerate(zip(amounts, offsets, strict=True)):
                bank.append({"id": f"B-{ref}-{index}", "reference": ref,
                             "posted_on": (base + timedelta(days=days)).isoformat(),
                             "counterparty": "Edge Vendor", "currency": "SGD",
                             "amount_cents": amount})
        bank.append({"id": "B-ORPHAN", "reference": "EDGE-ORPHAN",
                     "posted_on": base.isoformat(), "counterparty": "Edge Vendor",
                     "currency": "SGD", "amount_cents": -500})
        expected["EDGE-ORPHAN"] = "missing_in_ledger"
        for source in HEADERS:
            _write(data / f"{source}.csv", source,
                   ledger if source == "ledger" else bank if source == "bank" else [])
        db = connect(root / "edge.duckdb")
        try:
            ingest(db, data)
            rows = reconcile(db)
            predicted = {row["reference"]: row["status"] for row in rows}
            if expected.keys() != predicted.keys():
                raise ValueError("edge fixture and reconciliation references differ")
            trace_lengths = {row["figure_id"]: len(trace(db, row["figure_id"]))
                             for row in rows}
        finally:
            db.close()
    labels = sorted(set(expected.values()) | set(predicted.values()))
    by_status = {}
    for label in labels:
        tp = sum(expected[ref] == label and predicted[ref] == label for ref in expected)
        fp = sum(expected[ref] != label and predicted[ref] == label for ref in expected)
        fn = sum(expected[ref] == label and predicted[ref] != label for ref in expected)
        by_status[label] = {"tp": tp, "fp": fp, "fn": fn,
                            "precision": tp / (tp + fp) if tp + fp else None,
                            "recall": tp / (tp + fn) if tp + fn else None}
    report = {"cases": len(expected),
              "correct": sum(expected[ref] == predicted[ref] for ref in expected),
              "status_counts": dict(Counter(predicted.values())),
              "by_status": by_status, "traceable_figures": len(trace_lengths),
              "source_rows_traced": sum(trace_lengths.values()),
              "mismatches": [{"reference": ref, "expected": expected[ref],
                              "predicted": predicted[ref]} for ref in expected
                             if expected[ref] != predicted[ref]],
              "scope": "hand-authored local boundary cases; not external bank data"}
    if report_dir is not None:
        Path(report_dir).mkdir(parents=True, exist_ok=True)
        (Path(report_dir) / "independent_edge_eval.json").write_text(
            json.dumps(report, indent=2) + "\n", encoding="utf-8")
    return report


if __name__ == "__main__":
    print(json.dumps(run(Path("reports")), indent=2))
